function paintInput(id,value){const field=document.getElementById(id);if(field){field.focus();if(field.type==='search'&&value!==null)field.setSelectionRange(value,value);}}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target||target.disabled)return;event.preventDefault();if(!['dismiss-feedback','close','keep'].includes(target.dataset.action))$('#modal-alert').hidden=true;act(target.dataset.action);});
document.addEventListener('input',event=>{const field=event.target;
 if(field.id==='product-search'){const pos=field.selectionStart;st.query=field.value;const scroll=$('#main-content').scrollTop;$('#main-content').innerHTML=saleHtml();paintInput('product-search',pos);$('#main-content').scrollTop=scroll;return;}
 if(field.id==='tab-search'){const pos=field.selectionStart;st.boardQuery=field.value;$('#main-content').innerHTML=boardHtml();paintInput('tab-search',pos);return;}
 if(field.id==='cash-received'){st.received=field.value;const change=Math.max(0,Math.round(Number(st.received)*100)-Math.round(Number($('#tender-amount').value)*100));$('#change-preview strong').textContent=money(change);return;}
 if(field.id==='tender-amount'){st.amount=field.value;const change=Math.max(0,Math.round(Number(st.received)*100)-Math.round(Number(st.amount)*100));if($('#change-preview strong'))$('#change-preview strong').textContent=money(change);return;}
 if(field.id==='card-approved')st.paymentDraft.approved=field.checked;
 if(field.id==='blind-cash')st.blindCash=field.value;if(field.id==='blind-pieces')st.blindPieces=field.value;
 if(field.id==='global-query'){$$('#global-results button').forEach(b=>b.hidden=!b.textContent.toLocaleLowerCase('pt-BR').includes(field.value.toLocaleLowerCase('pt-BR')));}
});
document.addEventListener('change',event=>{if(event.target.id==='line-qty'){const l=lines().find(l=>targets().includes(l.id)),q=Number(event.target.value);if(!l)return;if(l.fired){feedback('A linha já foi enviada. Revise o efeito na cozinha antes de mudar a quantidade.','warning');event.target.value=l.qty;return;}if(!Number.isFinite(q)||q<=0||l.unit!=='kg'&&!Number.isInteger(q)){feedback('Informe uma quantidade válida para a unidade desta linha.','error');event.target.value=l.qty;return;}l.qty=q;render();}});
$('#sheet-scrim').addEventListener('click',()=>act('sheet-close'));
$('#modal').addEventListener('cancel',event=>{event.preventDefault();close();});
$('#modal').addEventListener('close',()=>{if($('#modal').open)return;modalDirty=false;modalReturn=null;if(lastFocus?.isConnected)lastFocus.focus();else if(st.sheet&&touchSheet())$('.ticket-close')?.focus();else $('#main-content').focus();});
document.addEventListener('keydown',event=>{const editing=event.target.matches('input,textarea,select,[contenteditable=true]');
 if(event.key==='Escape'&&!$('#modal').open){if(st.active){st.active=null;renderTicket();}else if(st.sheet)act('sheet-close');else if(st.scene==='payment')go('sale');return;}
 if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();act('global-search');return;}
 if($('#modal').open)return;
 const keys={F2:'go:board',F4:'checkout',F6:'customer',F7:'fulfillment',F8:'schedule',F9:'fire',F10:'transfer'};
 if(event.key==='F3'||event.key==='/'&&!editing){event.preventDefault();if(st.scene!=='sale')openTab(st.tab);$('#product-search')?.focus();return;}
 if(keys[event.key]){if(!['F2'].includes(event.key)&&!['sale','payment'].includes(st.scene))return;event.preventDefault();act(keys[event.key]);return;}
 if(event.key==='Enter'&&event.target.id==='tab-search'){event.preventDefault();act('open-ref');return;}
 if(event.key==='Enter'&&event.target.id==='product-search'){const ps=$$('.products .product:not([disabled])');if(ps.length===1){event.preventDefault();ps[0].click();}return;}
 if(event.key==='Enter'&&st.scene==='payment'&&!event.shiftKey&&!event.target.matches('textarea')){event.preventDefault();act('validate');return;}
 if(event.altKey&&event.key.toLowerCase()==='s'&&st.scene==='sale'){event.preventDefault();st.sheet=touchSheet();act('select-mode');return;}
 if(!editing&&st.scene==='sale'&&st.active&&!event.altKey&&!event.ctrlKey&&!event.metaKey&&/^[0-9]$/.test(event.key)){event.preventDefault();act('numpad:'+event.key);return;}
 if(event.key==='Delete'&&!editing&&st.scene==='sale'&&targets().length){event.preventDefault();act('remove');}
 if(event.key==='Tab'&&st.sheet&&touchSheet()){const nodes=$$('button:not([disabled]),input,select,textarea',$('#ticket')).filter(e=>e.getClientRects().length);if(!nodes.length)return;if(event.shiftKey&&document.activeElement===nodes[0]){event.preventDefault();nodes.at(-1).focus();}else if(!event.shiftKey&&document.activeElement===nodes.at(-1)){event.preventDefault();nodes[0].focus();}}
});
// Coleções e tabs com teclado, sem sequestrar as setas da edição numérica.
document.addEventListener('keydown',event=>{const rail=event.target.closest('.collections');if(!rail||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const nodes=$$('button',rail),at=nodes.indexOf(event.target);if(at<0)return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?nodes.length-1:(at+(event.key==='ArrowRight'?1:-1)+nodes.length)%nodes.length;nodes[next].focus();nodes[next].scrollIntoView({block:'nearest',inline:'nearest'});});
let dragStart=null;
$('#ticket').addEventListener('pointerdown',event=>{if(!event.target.closest('.ticket-resizer'))return;dragStart={x:event.clientX,width:$('#ticket').getBoundingClientRect().width};event.target.setPointerCapture(event.pointerId);event.preventDefault();});
$('#ticket').addEventListener('pointermove',event=>{if(!dragStart)return;const width=Math.max(300,Math.min(innerWidth*.48,dragStart.width+dragStart.x-event.clientX));$('#ticket').style.setProperty('--ticket-width',width+'px');});
$('#ticket').addEventListener('pointerup',()=>dragStart=null);$('#ticket').addEventListener('pointercancel',()=>dragStart=null);
$('#ticket').addEventListener('dblclick',event=>{if(event.target.closest('.ticket-resizer'))$('#ticket').style.setProperty('--ticket-width','340px');});
$('#ticket').addEventListener('keydown',event=>{if(!event.target.closest('.ticket-resizer')||!['ArrowLeft','ArrowRight','Home'].includes(event.key))return;event.preventDefault();const width=event.key==='Home'?340:$('#ticket').getBoundingClientRect().width+(event.key==='ArrowLeft'?20:-20);$('#ticket').style.setProperty('--ticket-width',Math.max(300,Math.min(innerWidth*.48,width))+'px');});
window.addEventListener('resize',()=>{renderTicket();if(!touchSheet())$('#sheet-scrim').hidden=true;});
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);st.scene=scenes.has(p.get('scene'))?p.get('scene'):'board';st.tab=p.get('tab')||st.tab;st.sheet=false;render();});
render();
